import ast, json, hashlib, importlib.util, subprocess
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
assert r['phase']=='propose'
assert set(p)=={'study','parent_trial','variants'}
assert p['parent_trial'] in {t['id'] for t in r['context']['history']}
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
if importlib.util.find_spec('jsonschema'):
 import jsonschema
 jsonschema.validate(p['study'],r['study_schema'])
 print('Full study JSON Schema validation passed.')
else:
 def check(value,schema,path='study'):
  types={'object':dict,'array':list,'string':str,'boolean':bool}
  if 'type' in schema: assert isinstance(value,types[schema['type']]),path
  if 'const' in schema: assert value==schema['const'],path
  if 'enum' in schema: assert value in schema['enum'],path
  if isinstance(value,dict):
   assert set(schema.get('required',[]))<=set(value),path
   if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),path
   for k,v in value.items():
    if k in schema.get('properties',{}):check(v,schema['properties'][k],path+'.'+k)
  if isinstance(value,list):
   assert len(value)>=schema.get('minItems',0),path
   for i,v in enumerate(value): check(v,schema.get('items',{}),path+'[%d]'%i)
  if isinstance(value,str):assert len(value)>=schema.get('minLength',0),path
 check(p['study'],r['study_schema'])
 print('Study validated against every active schema constraint using standard-library checker.')
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
normalized=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 path=Path(v['file'])
 assert path.name==v['file'] and path.suffix=='.py'
 assert v['role'] in {'candidate','control'}
 source=path.read_text()
 tree=ast.parse(source,filename=str(path))
 compile(tree,str(path),'exec')
 imports=[]
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): imports.extend(alias.name.split('.')[0] for alias in node.names)
  if isinstance(node,ast.ImportFrom): imports.append(node.module.split('.')[0])
 assert set(imports)<=allowed
 config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(config_node.value)==v['config']
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 assert {'__init__','forward','diagnostics'}<={n.name for n in model.body if isinstance(n,ast.FunctionDef)}
 assert hashlib.sha256(path.read_bytes()).hexdigest() in v['note']
 # Compare all implementation AST nodes except the literal per-file config.
 config_node.value=ast.Constant(None)
 normalized.append(ast.dump(tree,include_attributes=False))
 print(v['name']+': syntax, imports, API declaration, literal config and recorded hash passed.')
assert len(set(normalized))==1
assert any(v['role']=='candidate' for v in p['variants'])
base='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
for name in ['baseline_reference.py','history_baseline_static.py','history_baseline_pooled.py','history_baseline_din.py']:
 assert hashlib.sha256(Path(name).read_bytes()).hexdigest()==base
print('Implementations differ only in default mode; all reference files remain intact.')
print('PyTorch available:',importlib.util.find_spec('torch') is not None)
print('No models imported, numerical tests or training performed; syntax checks created no bytecode files.')
